-- Habbo's Collectibles hub content: the sets of the Collections tab, the Shop, mint token packs and the mintable furni of the Relics tab.
-- Shop offers, mint token offers and mintable items were read from the replies of Habbo US on AIR WIN63-202610201032-107964540
-- (NftStoreOffers, MintTokenOffers, CollectibleMintableItemTypes) on 2026-10-21. Sets, set membership, scores and rarities come from
-- Habbo's public collectibles shop list (collectibles.habbo.com/api/shop/items); set names from Habbo's collectibles.set.<id> texts.
-- Not observed on Habbo, chosen here: the boost score of a set is 0 and no set has a bonus or reward product; a relic (the collectible
-- a minted furni becomes, product nft_<furni>) is worth 10 and Common.
-- No monthly collector rewards are added, because Habbo's were not observed.
-- Every row is matched to this hotel's furniture by classname, so content for furni the hotel does not have is left out.
-- Idempotent: INSERT IGNORE keeps rows that already exist, including staff edits.

CREATE TEMPORARY TABLE collectible_sets_111 (id VARCHAR(64) NOT NULL PRIMARY KEY, name VARCHAR(100) NOT NULL, sort_order INT NOT NULL) ENGINE=MEMORY;

CREATE TEMPORARY TABLE collectible_items_111 (product_code VARCHAR(64) NOT NULL PRIMARY KEY, collection_id VARCHAR(64) DEFAULT NULL,
    score INT NOT NULL, rarity VARCHAR(32) NOT NULL, sort_order INT NOT NULL) ENGINE=MEMORY;

-- A set is only added when at least one of its products has furni in this hotel.
SELECT s.id, s.name, 0, s.sort_order FROM collectible_sets_111 s
WHERE EXISTS (SELECT 1 FROM collectible_items_111 i JOIN furniture f ON f.furnidata_classname = i.product_code WHERE i.collection_id = s.id);

-- Clothing furni become clothing products (type 11) with their figure set ids; other furni are floor (1) or wall (0) products.
SELECT i.product_code, i.collection_id,
    IF(f.interaction_type = 'purchasable_clothing', 11, IF(f.type = 'i', 0, 1)),
    f.sprite_id, i.score, i.rarity, '',
    IF(f.interaction_type = 'purchasable_clothing' AND f.custom_params REGEXP '^[0-9]+(,[0-9]+)*$', f.custom_params, ''),
    i.sort_order
FROM collectible_items_111 i
JOIN furniture f ON f.furnidata_classname = i.product_code;

CREATE TEMPORARY TABLE collectible_offers_111 (product_code VARCHAR(64) NOT NULL PRIMARY KEY, emerald_price INT NOT NULL, is_featured TINYINT(1) NOT NULL,
    is_limited TINYINT(1) NOT NULL, mint_limit INT NOT NULL, sort_order INT NOT NULL) ENGINE=MEMORY;

SELECT o.product_code, o.emerald_price, o.is_featured, o.is_limited, o.mint_limit, o.sort_order FROM collectible_offers_111 o
JOIN collectible_products p ON p.product_code = o.product_code;


CREATE TEMPORARY TABLE collectible_mintables_111 (item_type CHAR(1) NOT NULL, item_name VARCHAR(70) NOT NULL, product_code VARCHAR(64) NOT NULL,
    token_price INT NOT NULL, starts_at DATETIME DEFAULT NULL, ends_at DATETIME DEFAULT NULL, region_locked TINYINT(1) NOT NULL,
    limited_edition TINYINT(1) NOT NULL, seq INT NOT NULL PRIMARY KEY) ENGINE=MEMORY;

SELECT m.item_type, f.sprite_id, m.product_code, m.token_price, m.starts_at, m.ends_at, m.region_locked, m.limited_edition FROM collectible_mintables_111 m
JOIN furniture f ON f.furnidata_classname = m.item_name AND f.type = m.item_type
JOIN collectible_products p ON p.product_code = m.product_code
ORDER BY m.seq;

DROP TEMPORARY TABLE collectible_mintables_111;
DROP TEMPORARY TABLE collectible_offers_111;
DROP TEMPORARY TABLE collectible_items_111;
DROP TEMPORARY TABLE collectible_sets_111;
